/* Here is an example SQL script that creates an IoT
table and populates it with data

These sql script can be run automatically upon initializing
a postgres database container */

CREATE EXTENSION IF NOT EXISTS timescaledb;
CREATE TABLE example_data(
	id SERIAL NOT NULL,
	time TIMESTAMP WITH TIME ZONE NOT NULL,
	uuid INT,
	y DOUBLE PRECISION,
	state integer,
	metadata JSONB
);

/* Example command to convert postgresql table into a timescale hypertable */
SELECT create_hypertable('example_data', 'time', if_not_exists => TRUE);

/* Create an index on the uuid */
CREATE INDEX IF NOT EXISTS index_sensor_id ON example_data("uuid");

/* Create a GIN index to allow indexing of JSONB data */
CREATE INDEX IF NOT EXISTS datagin ON example_data USING gin (metadata);


/* example table to store the output of an ML model */
CREATE TABLE ai_model(
	id SERIAL NOT NULL,
	time TIMESTAMP WITH TIME ZONE,
	model_output JSONB
);
SELECT create_hypertable('ai_model', 'time', if_not_exists => TRUE);


